#!/bin/zsh
set -euo pipefail
cd -- "${0:A:h:h}"
[[ -f package.json && -d src/renderer/src ]] || { print -u2 'プロジェクトルートを確認してください'; exit 1; }
command -v node >/dev/null
command -v npm >/dev/null
git rev-parse --is-inside-work-tree >/dev/null
if [[ -n "$(git status --porcelain --untracked-files=all -- . ':!gemini-scripts')" ]]; then
  print -u2 '未コミットの変更があります。先に整理してください（gemini-scripts以外）。'
  exit 1
fi
